using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Runtime.Serialization.Json;using GlassBoard;
public static class UserFeedbackTests {
    static void Check(bool value,string message){if(!value)throw new Exception(message);}
    static T Json<T>(T value){using(var stream=new MemoryStream()){var serializer=new DataContractJsonSerializer(typeof(T));serializer.WriteObject(stream,value);stream.Position=0;return (T)serializer.ReadObject(stream);}}
    public static int Main(){
        var prefs=new Preferences();var app=new Entry{Name="编辑器",Path=@"C:\Desktop\Edit.lnk",LaunchTarget=@"C:\Apps\Edit.exe",LaunchArguments="--profile main",Pinned=true};prefs.Apps.Add(app);prefs.Normalize();var history=new BoardEditHistory();var before=BoardEditState.Capture(prefs);EntryRules.Remove(prefs,new[]{app.Path},"全部");history.Remember(before,prefs,"移除");
        var alias=FeatureRules.Copy(app);alias.Path=@"C:\StartMenu\Editor.lnk";Check(RemovalRules.Blocked(prefs,alias),"alternate shortcut cannot resurrect removed app");var other=FeatureRules.Copy(alias);other.LaunchArguments="--profile other";Check(!RemovalRules.Blocked(prefs,other),"distinct launch arguments remain independent");
        var round=Json(prefs);round.Normalize();Check(RemovalRules.Blocked(round,alias),"identity tombstone persists on restart");round.Apps.Add(alias);round.Normalize();Check(round.Apps.Count==1&&!RemovalRules.Blocked(round,alias),"valid saved live entry wins over a stale tombstone");RemovalRules.Forget(round,alias);round.Apps.Add(alias);round.Normalize();Check(round.Apps.Count==1,"explicit re-add restores an entry");
        history.Undo(prefs);Check(prefs.Apps.Count==1&&!RemovalRules.Blocked(prefs,alias),"undo removes identity tombstone");history.Redo(prefs);Check(prefs.Apps.Count==0&&RemovalRules.Blocked(prefs,alias),"redo reapplies persistent deletion");
        var shared=new Preferences();var entry=FeatureRules.Copy(app);entry.ExtraGroups=new List<string>{"办公"};entry.Group="创作";shared.Apps.Add(entry);EntryRules.Remove(shared,new[]{entry.Path},"创作");Check(shared.Apps.Count==1&&shared.RemovedIdentities.Count==0,"scoped membership removal does not suppress other groups");
        var old=new Preferences();old.Apps.Add(alias);new RemovalJournal{Paths=new List<string>{app.Path},Identities=prefs.RemovedIdentities.ToList()}.Merge(old);old.Normalize();Check(old.Apps.Count==1,"normalization preserves live entries; journals only prune recovery snapshots");
        Check(DocumentRules.Supported("report.DOCX")&&DocumentRules.Supported("sheet.xlsx")&&EntryRules.Importable("slides.pptx")&&!StartupEntryRules.Candidate("sheet.xlsx"),"manual office imports do not become automatic startup scans");Check(EntryPathRules.Name("report.docx")=="report.docx","document labels retain extension");
        Check(LayoutRules.GlassOpacity(0)==0&&LayoutRules.GlassOpacity(100)==100&&LayoutRules.GlassOpacity(-10)==0&&LayoutRules.GlassOpacity(double.NaN)==72,"all glass opacity endpoints");
        prefs=new Preferences();prefs.Widgets.HideControls=true;prefs.Widgets.Position(0).HideControls=false;var restored=Json(prefs);restored.Normalize();Check(restored.Widgets.HideControls&&!restored.Widgets.Position(0).HideControls.Value,"global widget controls and individual overrides persist");
        prefs.BoardMaterial.Kind=3;prefs.BoardMaterial.Tint="#334A70";prefs.BoardMaterial.Grain=.4;prefs.Dock.Material.Kind=2;prefs.Widgets.Material.Kind=1;var scheme=Json(FeatureRules.Capture(prefs,"材质"));var target=new Preferences();FeatureRules.Apply(target,scheme);Check(target.BoardMaterial.Kind==3&&target.BoardMaterial.Tint=="#334A70"&&target.Dock.Material.Kind==2&&target.Widgets.Material.Kind==1,"independent material choices survive appearance schemes");var copy=target.Dock.Copy();copy.Material.Tint="#FFFFFF";Check(target.Dock.Material.Tint!="#FFFFFF","material drafts are deep copies");
        var material=new MaterialOptions{Kind=99,Tint="bad",Gloss=double.NaN,Grain=2};material.Normalize();Check(material.Kind==3&&material.Tint==""&&material.Gloss==.15&&material.Grain==1,"material input bounds");
        Check(GameModeRules.Suppressed(true,false,false,false)&&GameModeRules.Suppressed(false,true,true,false)&&!GameModeRules.Suppressed(false,true,false,false)&&!GameModeRules.Suppressed(false,true,true,true),"manual/fullscreen/desktop game mode decisions");
        Console.WriteLine("PASS: deletion aliases/arguments/restart/re-add/undo/shared groups/journal, office documents, 0-100 opacity, widget button flags, independent materials/copies/schemes, game mode rules.");return 0;
    }
}
